/* Types */
/**
 *  Every error the backend can report to the frontend.
 * 
 *  - `thiserror::Error` writes the `Display` impl from the `#[error("...")]`
 *    strings so we never hand-write `impl Display`.
 *  - `Serialize` + `Type` make it crossable to TypeScript. With serde's
 *    adjacent tagging it becomes `{ "kind": "validation", "message": "..." }`,
 *    which is the shape CLAUDE.md asks for.
 *  - Each variant carries a `String` rather than the original error (such as
 *    `std::io::Error`) because those originals are not serialisable.
 */
export type AppError = { kind: "io"; message: string } | { kind: "validation"; message: string } | { kind: "notFound"; message: string } | { kind: "database"; message: string } | { kind: "internal"; message: string };

/**  Name and version of the running app, as read from `tauri.conf.json`. */
export type AppInfo = {
	name: string,
	version: string,
};

/**
 *  Per-user app preferences (not per-world), stored in the app config dir.
 * 
 *  `#[serde(default)]` on the struct means any field missing from the file
 *  falls back to its value in `Default::default()`, so files written by an
 *  older version still load after new settings are added.
 */
export type AppSettings = {
	theme?: Theme,
	/**  Milliseconds of inactivity before edits are saved. */
	autosaveDelayMs?: number,
	/**  Lore editor font size in pixels. */
	editorFontSize?: number,
};

/**  An imported image file. The file lives at `<world>/assets/<id>.<ext>`. */
export type Asset = {
	id: string,
	/**  The original file name, for display only. */
	fileName: string,
	mime: string,
	width: number | null,
	height: number | null,
	createdAt: string,
	/**
	 *  Absolute path of the image file. NOT stored in the database: the
	 *  service fills it in from the open world's folder. The frontend turns it
	 *  into a URL with `convertFileSrc(path)`.
	 */
	path: string,
	/**
	 *  Absolute path of the thumbnail (max 512px PNG), or `None` while it is
	 *  still being generated on the background thread (or if that failed).
	 */
	thumbPath: string | null,
};

/**  One entity that mentions another, with a snippet of the surrounding text. */
export type Backlink = {
	sourceId: string,
	sourceType: string,
	sourceName: string,
	snippet: string,
};

/**  A calendar row. */
export type Calendar = {
	id: string,
	name: string,
	definition: CalendarDefinition,
	isDefault: boolean,
};

/**  A day number broken into calendar parts. */
export type CalendarDate = {
	/**  Index into `definition.eras`. */
	eraIndex: number,
	eraName: string,
	/**
	 *  Year within the era; 1 is the first year. Dates before the first era
	 *  continue downwards: 0, -1, -2, ...
	 */
	year: number,
	/**  1-based. */
	month: number,
	monthName: string,
	/**  1-based day of the month. */
	day: number,
	/**  Name of the weekday, or `None` when the calendar has no weekdays. */
	weekday: string | null,
};

/**  Stored as JSON in `calendars.definition`. */
export type CalendarDefinition = {
	months: Month[],
	/**  Names of the days of the week; may be empty (no weekdays). */
	weekdays: string[],
	/**  Sorted by `start_day`, at least one. */
	eras: Era[],
};

/**  How [`format`](crate::services::calendar::format) writes a date. */
export type DateStyle = 
/**  `15 Month 3, 1203 AF` */
"full" | 
/**  `15/3/1203 AF` */
"short" | 
/**  `Month 3, 1203 AF` */
"monthYear" | 
/**  `1203 AF` */
"year" | 
/**  `Month 3` (handy for tick labels) */
"month" | 
/**  `15` (handy for tick labels) */
"day";

/**
 *  The rich-text lore of one entity. One document per entity, created on
 *  first save.
 */
export type Document = {
	entityId: string,
	/**
	 *  TipTap JSON, kept as a string: the backend only stores it, the editor
	 *  is the one that understands its shape.
	 */
	content: string,
	/**  Plain text extracted by the editor, used for search (Phase 5). */
	plainText: string,
	updatedAt: string,
};

/**  A full entity row. */
export type Entity = {
	id: string,
	/**
	 *  `type` is a Rust keyword, so the field is `entity_type` in Rust and
	 *  renamed to `type` in JSON/TypeScript.
	 */
	type: string,
	name: string,
	summary: string,
	/**
	 *  Type-specific fields as a JSON object (see `entity_type::FieldDef`).
	 *  Exported to TypeScript as `{ [key: string]: unknown }` because specta
	 *  refuses `serde_json::Value`'s 64-bit numbers.
	 */
	properties: { [key in string]: unknown },
	createdAt: string,
	updatedAt: string,
};

/**  Input for `update_entity`: only the fields that are `Some` change. */
export type EntityPatch = {
	name: string | null,
	summary: string | null,
	properties: { [key in string]: unknown } | null,
};

/**  The light version used by the sidebar list. */
export type EntitySummary = {
	id: string,
	type: string,
	name: string,
	updatedAt: string,
};

export type EntityTypeDef = {
	/**  Stored in `entities.type`, e.g. `character`. */
	key: string,
	label: string,
	plural: string,
	/**  A lucide icon name the frontend maps to a component. */
	icon: string,
	fields: FieldDef[],
};

/**  A named span of years, e.g. "Age of Founding" (AF). */
export type Era = {
	name: string,
	/**  Short suffix used when formatting, e.g. "AF". Falls back to `name`. */
	abbreviation: string | null,
	/**
	 *  Day number on which the era starts; year 1 of the era is the calendar
	 *  year containing this day.
	 */
	startDay: number,
};

/**  An event as shown on the timeline: its entity name plus the dates. */
export type EventSummary = {
	entityId: string,
	name: string,
	/**  Day number from the world epoch; may be negative. */
	startDay: number,
	/**  `None` = a single-day event (drawn as a point). */
	endDay: number | null,
	/**  1 (minor) to 5 (major). */
	importance: number,
	calendarId: string,
};

export type FieldDef = {
	/**  Key inside the entity's `properties` JSON object. */
	key: string,
	label: string,
	kind: FieldKind,
	/**  Choices for `Select`; empty for other kinds. */
	options: string[],
};

/**  How a type-specific field is edited. */
export type FieldKind = "text" | "number" | "select";

/**
 *  A day number or year in command arguments (an integer that fits a JS number).
 * 
 *  specta refuses to export `i64` (JavaScript numbers lose precision above
 *  2^53). Day numbers are limited to +/- `MAX_DAY` (10^12), far below that
 *  limit, so we tell specta to describe this type as a plain TypeScript
 *  `number`. `serde(transparent)` makes it travel as a bare number in JSON.
 */
export type JsInt = number;

/**  One place where an entity appears as a pin ("appears on maps"). */
export type MapAppearance = {
	mapEntityId: string,
	mapName: string,
	objectId: string,
	geometry: MapGeometry,
};

/**  Everything the map view needs in one call. */
export type MapData = {
	map: MapInfo,
	layers: MapLayer[],
	objects: MapObject[],
};

/**
 *  Which kinds of map object exist. Serialised as `{ "kind": "pin", "x": 1, "y": 2 }`.
 * 
 *  This is an "internally tagged" enum: serde writes the variant name into a
 *  `kind` field next to the variant's own fields. Phase 10 adds `Path`,
 *  `Area` and `Label` variants. The same JSON is stored in
 *  `map_objects.geometry`; coordinates are in map pixels (origin top-left).
 */
export type MapGeometry = { kind: "pin"; x: number | null; y: number | null };

/**  A map row plus its background asset (if one has been set). */
export type MapInfo = {
	/**  `maps.id` (internal; commands address maps by `entity_id`). */
	id: string,
	/**  The entity (type `map`) that represents this map in the sidebar. */
	entityId: string,
	name: string,
	/**  Pixels; 0 until a background is set. */
	width: number,
	height: number,
	background: Asset | null,
};

export type MapLayer = {
	id: string,
	mapId: string,
	name: string,
	sortOrder: number,
	visible: boolean,
};

export type MapObject = {
	id: string,
	layerId: string,
	geometry: MapGeometry,
	/**  Free-form style object (colour, size...). `{}` by default. */
	style: { [key in string]: unknown },
	/**  The linked entity, or `None` for an unlinked pin. */
	entityId: string | null,
	/**
	 *  Convenience copies from the linked entity, so the map can pick an icon
	 *  and show a hover label without extra lookups.
	 */
	entityType: string | null,
	entityName: string | null,
	createdAt: string,
	updatedAt: string,
};

/**
 *  Input for `update_map_object`: only the `Some` fields change.
 *  `unlink_entity: true` clears the link (a plain `None` entity id means
 *  "leave it alone", so a separate flag is needed to remove it).
 */
export type MapObjectPatch = {
	geometry: MapGeometry | null,
	style: { [key in string]: unknown } | null,
	entityId: string | null,
	unlinkEntity?: boolean,
};

/**  One month of the year. */
export type Month = {
	name: string,
	/**  Number of days in the month (must be at least 1). */
	days: number,
};

/**  Input for `create_entity`. */
export type NewEntity = {
	type: string,
	name: string,
};

/**
 *  Input for `create_map_object`. The `kind` column is derived from the
 *  geometry variant, so it cannot disagree with it.
 */
export type NewMapObject = {
	layerId: string,
	geometry: MapGeometry,
	/**  Defaults to `{}` when omitted. */
	style: { [key in string]: unknown } | null,
	entityId: string | null,
};

/**  One row of the "recent worlds" list on the welcome screen. */
export type RecentWorld = {
	name: string,
	path: string,
	/**  UTC ISO-8601 text. */
	lastOpenedAt: string,
	/**  False when the folder (or its `world.json`) no longer exists. */
	available: boolean,
};

/**  One hit from the full-text search, best match first. */
export type SearchResult = {
	entityId: string,
	entityType: string,
	name: string,
	/**
	 *  A short excerpt of the best-matching text. Matched terms are wrapped
	 *  in U+0002 (start) and U+0003 (end); an ellipsis (U+2026) marks
	 *  trimmed text.
	 */
	snippet: string,
};

/**  Colour scheme preference. Serialised as `"light"`, `"dark"` or `"system"`. */
export type Theme = "light" | "dark" | "system";

/**  What the frontend needs to know about the currently open world. */
export type WorldSummary = {
	name: string,
	/**  Absolute path of the world folder, as a string for the frontend. */
	path: string,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

